def minutes_to_time_str(minutes):
    m = minutes % 1440
    return f'{m//60:02d}:{m%60:02d}'

def add_minutes_with_day_offset(time_str, minutes):
    h, m = time_str.split(':')
    total = int(h)*60 + int(m) + minutes
    day_offset = total // 1440
    rem = total % 1440
    return (day_offset, f'{rem//60:02d}:{rem%60:02d}')

def minutes_between_times(t1, t2):
    def to_min(t):
        h, m = t.split(':')
        return int(h)*60 + int(m)
    a, b = to_min(t1), to_min(t2)
    diff = b - a
    if diff <= 0:
        diff += 1440
    return diff

def time_diff_signed(t1, t2):
    def to_min(t):
        h, m = t.split(':')
        return int(h)*60 + int(m)
    return to_min(t2) - to_min(t1)

def hms_to_seconds(time_str):
    h, m, s = time_str.split(':')
    return int(h)*3600 + int(m)*60 + int(s)

def sum_durations(durations):
    total = 0
    for d in durations:
        h, m = d.split(':')
        total += int(h)*60 + int(m)
    return f'{total//60:02d}:{total%60:02d}'

def total_minutes_worked(sessions):
    def to_min(t):
        h, m = t.split(':')
        return int(h)*60 + int(m)
    total = 0
    for start, end in sessions:
        total += to_min(end) - to_min(start)
    return total

def earlier_time(t1, t2):
    def to_min(t):
        h, m = t.split(':')
        return int(h)*60 + int(m)
    return t1 if to_min(t1) <= to_min(t2) else t2

def sort_times(times):
    def to_min(t):
        h, m = t.split(':')
        return int(h)*60 + int(m)
    return sorted(times, key=to_min)

def meeting_overlap_minutes(s1, e1, s2, e2):
    start = max(s1, s2)
    end = min(e1, e2)
    return max(0, end - start)

def merged_busy_minutes(intervals):
    if not intervals:
        return 0
    ivs = sorted(intervals)
    total = 0
    cur_s, cur_e = ivs[0]
    for s, e in ivs[1:]:
        if s > cur_e:
            total += cur_e - cur_s
            cur_s, cur_e = s, e
        else:
            cur_e = max(cur_e, e)
    total += cur_e - cur_s
    return total
